  function toKebab(str) {
    return String(str || "").trim().replace(/([a-z0-9])([A-Z])/g, "$1-$2").toLowerCase();
  }

  function renderIconElement(el) {
    const rawName = el.getAttribute("data-lucide");
    if (!rawName) return;
    const key = toKebab(rawName);
    const inner = ICONS[key] || ICONS["download"];
    const svg = document.createElementNS(SVG_NS, "svg");
    svg.setAttribute("xmlns", SVG_NS);
    svg.setAttribute("width", "24");
    svg.setAttribute("height", "24");
    svg.setAttribute("viewBox", "0 0 24 24");
    svg.setAttribute("fill", "none");
    svg.setAttribute("stroke", "currentColor");
    svg.setAttribute("stroke-width", "2");
    svg.setAttribute("stroke-linecap", "round");
    svg.setAttribute("stroke-linejoin", "round");
    svg.setAttribute("data-lucide", key);
    const cls = el.getAttribute("class") || "";
    svg.setAttribute("class", ("lucide lucide-" + key + " " + cls).trim());
    if (el.getAttribute("style")) svg.setAttribute("style", el.getAttribute("style"));
    if (el.id) svg.id = el.id;
    svg.innerHTML = inner;
    if (el.parentNode) {
      el.parentNode.replaceChild(svg, el);
    }
  }

  function createIcons() {
    document.querySelectorAll("i[data-lucide], span[data-lucide]").forEach(renderIconElement);
  }

  global.lucide = { createIcons: createIcons, icons: ICONS };
  global.refreshIcons = createIcons;

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", createIcons);
  } else {
    createIcons();
  }

  const observer = new MutationObserver(function () {
    if (document.querySelector("i[data-lucide], span[data-lucide]")) {
      createIcons();
    }
  });
  if (document.documentElement) {
    observer.observe(document.documentElement, { childList: true, subtree: true });
  }
